from pathlib import Path
Path('tests/usage-write-contract.test.ts').write_text('''import { beforeEach, describe, expect, mock, test } from "bun:test";
import type { UsageWriteRequest, UsageWriteResult } from "../src/core/model-usage.js";

const exec = mock((): unknown => Buffer.from("Recorded 1 event(s)"));
mock.module("node:child_process", () => ({ execFileSync: exec }));
mock.module("../src/lib/logger.js", () => ({ debug: () => {} }));
const { recordModelUsage, createOpenCodeUsageRecorder } = await import("../src/core/model-usage.js");
const events = [{ kind: "session", name: "model_usage", session: "s" }];
const request = { binary: "fake", cwd: "/cwd", events };
const part = {
  type: "step-finish", id: "p", sessionID: "s", messageID: "m",
  tokens: { input: 1 },
};
beforeEach(() => {
  exec.mockReset();
  exec.mockReturnValue(Buffer.from("Recorded 1 event(s)"));
});

describe("usage write request/result contract", () => {
  test("empty batches acknowledge without execution", () => {
    expect(recordModelUsage({ ...request, events: [] })).toEqual({ status: "acknowledged", recorded: 0 });
    expect(exec).not.toHaveBeenCalled();
  });
  test("full acknowledgments preserve JSONL and execution options", () => {
    const batch = [...events, ...events];
    exec.mockReturnValue(Buffer.from("  rEcOrDeD 2 EvEnT(s), SkIpPeD 0\\n  "));
    expect(recordModelUsage({ ...request, events: batch })).toEqual({ status: "acknowledged", recorded: 2 });
    expect(exec).toHaveBeenCalledWith("fake", ["observe", "record", "--stdin"], {
      cwd: "/cwd", input: batch.map(e => JSON.stringify(e)).join("\\n") + "\\n",
      timeout: 10000, stdio: ["pipe", "pipe", "pipe"],
    });
  });
  test("missing, malformed, mismatched and skipped responses are invalid acknowledgments", () => {
    for (const output of [undefined, null, "", "ok", "Recorded 0 event(s)", "Recorded 2 event(s)", "Recorded 1 event(s), skipped 1", "Recorded 1 event(s) extra"]) {
      exec.mockReturnValue(output);
      expect(recordModelUsage(request)).toEqual({ status: "unacknowledged", reason: "invalid-ack" });
    }
  });
  test("execution errors return write-error without retrying", () => {
    exec.mockImplementation(() => { throw new Error("write failed"); });
    expect(recordModelUsage(request)).toEqual({ status: "unacknowledged", reason: "write-error" });
    expect(exec).toHaveBeenCalledTimes(1);
  });
  test("serialization errors return write-error before execution", () => {
    const broken = { ...events[0], toJSON() { throw new Error("serialization failed"); } };
    expect(recordModelUsage({ ...request, events: [broken] })).toEqual({ status: "unacknowledged", reason: "write-error" });
    expect(exec).not.toHaveBeenCalled();
  });
  test("only acknowledged fingerprints are cached, with revisions and cwd scoped", () => {
    const calls: UsageWriteRequest[] = [];
    const record = createOpenCodeUsageRecorder((request): UsageWriteResult => {
      calls.push(request);
      return calls.length === 1
        ? { status: "unacknowledged", reason: "invalid-ack" }
        : { status: "acknowledged", recorded: request.events.length };
    });
    const input = { binary: "fake", cwd: "/cwd", part };
    expect(record({ ...input, part: null })).toBeUndefined();
    record(input);
    record(input);
    record(input);
    record({ ...input, part: { ...part, tokens: { input: 2 } } });
    record({ ...input, cwd: "/other" });
    expect(calls).toHaveLength(4);
    expect(calls[0]).toMatchObject({ binary: "fake", cwd: "/cwd", events: [{ name: "model_usage", attrs: { uncached_input_tokens: "1" } }] });
  });
  test("recorders are independent and evict the oldest of 1024 entries", () => {
    const writer = mock((request: UsageWriteRequest): UsageWriteResult => ({ status: "acknowledged", recorded: request.events.length }));
    const record = createOpenCodeUsageRecorder(writer);
    const input = { binary: "fake", cwd: "/cwd", part };
    record(input);
    createOpenCodeUsageRecorder(writer)(input);
    expect(writer).toHaveBeenCalledTimes(2);
    for (let i = 1; i < 1024; i++) record({ ...input, part: { ...part, id: `p${i}` } });
    record(input); // A duplicate must not refresh insertion order.
    expect(writer).toHaveBeenCalledTimes(1025);
    record({ ...input, part: { ...part, id: "overflow" } });
    record(input);
    expect(writer).toHaveBeenCalledTimes(1027);
  });
});
''')
